  ('cfa98b94-fa28-4de2-a818-9e387e9e2872'::uuid, true, 1000, 'Historical import', '2025 entry confirmed paid by commissioner', '2025-03-20T12:36:04.985Z'::timestamptz, '8aad4281-8cc3-4521-b994-fb2a761cfe18'::uuid, '2025-03-20T12:36:04.985Z'::timestamptz, '2025-03-20T12:36:04.985Z'::timestamptz),
  ('0d41c45f-be6a-4afd-adbf-894027acc7ea'::uuid, true, 1000, 'Historical import', '2025 entry confirmed paid by commissioner', '2025-03-20T15:48:46.588Z'::timestamptz, '8aad4281-8cc3-4521-b994-fb2a761cfe18'::uuid, '2025-03-20T15:48:46.588Z'::timestamptz, '2025-03-20T15:48:46.588Z'::timestamptz)
on conflict (bracket_id) do update set
  is_paid = excluded.is_paid,
  amount_cents = excluded.amount_cents,
  payment_method = excluded.payment_method,
  note = excluded.note,
  paid_at = excluded.paid_at,
  marked_by = excluded.marked_by,
  updated_at = excluded.updated_at;

do $$
begin
    if (
      select count(*)
      from public.espn_games
      where season_year = 2025
        and round_code in (
          'PLAY_IN',
          'ROUND_OF_64',
          'ROUND_OF_32',
          'SWEET_16',
          'ELITE_8',
          'FINAL_FOUR',
          'CHAMPIONSHIP'
        )
    ) <> 67 then
      raise exception 'Historical season 2025 does not contain 67 tournament games';
    end if;

    if (
      select count(*)
      from public.brackets
      where season_year = 2025
        and user_id = '8aad4281-8cc3-4521-b994-fb2a761cfe18'::uuid
    ) <> 32 then
      raise exception 'Historical season 2025 has an unexpected bracket count';
    end if;

    if (
      select count(*)
      from public.brackets as bracket
      join public.bracket_payments as payment
        on payment.bracket_id = bracket.id
      where bracket.season_year = 2025
        and bracket.user_id = '8aad4281-8cc3-4521-b994-fb2a761cfe18'::uuid
        and payment.is_paid
    ) <> 32 then
      raise exception 'Historical season 2025 has an unexpected paid count';
    end if;

    if not exists (
      select 1
      from public.espn_games
      where season_year = 2025
        and round_code = 'CHAMPIONSHIP'
        and completed
    ) then
      raise exception 'Historical season 2025 has no completed championship';
    end if;
end
$$;
